"use client"

import { useAuth } from "@/lib/auth-context"
import { Clock, Apple, Coffee, Moon } from "lucide-react"
import { useEffect, useState } from "react"

interface MealRecord {
  id: number
  meal_type: string
  meal_name: string
  timestamp: string
  status: string
}

export default function StudentDashboard() {
  const { user } = useAuth()
  const [meals, setMeals] = useState<MealRecord[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    // Mock data for student meals
    setMeals([
      {
        id: 1,
        meal_type: "breakfast",
        meal_name: "Pancakes & Juice",
        timestamp: "2024-01-15 08:30 AM",
        status: "completed",
      },
      {
        id: 2,
        meal_type: "lunch",
        meal_name: "Biryani & Salad",
        timestamp: "2024-01-15 12:45 PM",
        status: "completed",
      },
      {
        id: 3,
        meal_type: "dinner",
        meal_name: "Pasta & Garlic Bread",
        timestamp: "2024-01-15 06:15 PM",
        status: "pending",
      },
    ])
    setLoading(false)
  }, [])

  const getMealIcon = (mealType: string) => {
    switch (mealType) {
      case "breakfast":
        return <Coffee className="w-5 h-5 text-blue-400" />
      case "lunch":
        return <Apple className="w-5 h-5 text-green-400" />
      case "dinner":
        return <Moon className="w-5 h-5 text-yellow-400" />
      default:
        return <Clock className="w-5 h-5" />
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-zinc-950 to-zinc-900 p-4 sm:p-6">
      <div className="max-w-4xl mx-auto">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-white mb-2">Welcome, {user?.name}</h1>
          <p className="text-zinc-400">Your meal access dashboard</p>
        </div>

        {/* Quick Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
          <div className="bg-zinc-900 border border-zinc-800 rounded-lg p-6">
            <div className="text-zinc-400 text-sm font-medium">Today's Meals</div>
            <div className="text-3xl font-bold text-white mt-2">3</div>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 rounded-lg p-6">
            <div className="text-zinc-400 text-sm font-medium">Completed</div>
            <div className="text-3xl font-bold text-green-500 mt-2">2</div>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 rounded-lg p-6">
            <div className="text-zinc-400 text-sm font-medium">Remaining</div>
            <div className="text-3xl font-bold text-yellow-500 mt-2">1</div>
          </div>
        </div>

        {/* Meal Records */}
        <div className="bg-zinc-900 border border-zinc-800 rounded-lg overflow-hidden">
          <div className="p-6 border-b border-zinc-800">
            <h2 className="text-xl font-bold text-white">Today's Meals</h2>
          </div>

          {loading ? (
            <div className="p-12 text-center text-zinc-400">Loading meals...</div>
          ) : (
            <div className="divide-y divide-zinc-800">
              {meals.map((meal) => (
                <div key={meal.id} className="p-6 hover:bg-zinc-800/50 transition">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      {getMealIcon(meal.meal_type)}
                      <div>
                        <div className="font-semibold text-white capitalize">{meal.meal_type}</div>
                        <div className="text-sm text-zinc-400">{meal.meal_name}</div>
                        <div className="text-xs text-zinc-500 mt-1">{meal.timestamp}</div>
                      </div>
                    </div>
                    <span
                      className={`px-3 py-1 rounded-full text-xs font-medium ${
                        meal.status === "completed" ? "bg-green-900 text-green-200" : "bg-yellow-900 text-yellow-200"
                      }`}
                    >
                      {meal.status.charAt(0).toUpperCase() + meal.status.slice(1)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
